const s=input.state,e=input.event;
if(e.type==='action'){
  const a=e.actionId;
  if(a==='restart'){
    s.score=0;s.won=false;s.playable=true;s.s2=false;s.s5=false;s.s8=false;
    s.star2='☆';s.star5='☆';s.star8='☆';
    s.message='Соберите три звезды: клетки 2, 5 и 8.';
  } else if(!s.playable){
    s.message='Поле заблокировано. Нажмите «Заново».';
  } else {
    const map={cell2:'s2',cell5:'s5',cell8:'s8'};
    const k=map[a];
    if(k&&s[k]){
      s.message='Эта звезда уже собрана.';
    } else if(k){
      s[k]=true;s.score=s.score+1;
      if(a==='cell2')s.star2='★';
      if(a==='cell5')s.star5='★';
      if(a==='cell8')s.star8='★';
      if(s.score>=3){s.won=true;s.playable=false;s.message='Победа! Все три звезды собраны.';}
      else{s.message='Звезда собрана! Очки: '+s.score+' из 3.';}
    } else {
      s.message='Пустая клетка. Очков нет.';
    }
  }
}
const commands=[{type:'roundRect',x:0,y:0,width:320,height:16,radius:8,color:'muted'},{type:'roundRect',x:0,y:0,width:Math.max(1,Math.round(320*s.score/3)),height:16,radius:8,color:'accent'}];
return {state:s,surfaces:{board:{commands}}};
